"""Reuse the JIRA plugin's own local authorization; no live credentials/network."""
import argparse
import contextlib
import copy
import hashlib
import io
import json
import os
import base64
import subprocess
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from unittest.mock import patch

from test_productivity import Base, j

# Generated by quectel-cli jira +token-create using fixture-user/fixture-password,
# in an isolated temporary token store. This is not an employee credential.
FIXTURE_TOKEN = 'vU8WJ-9MB8UmeLNpYvtRjXmbewHJfwcIvSrAw2_8r7o'
LEGACY_PASSWORD = '89nxScpzmWw_FlXNp_rzTi0Ycsu6bffsuoatbjbwE1I'
FIXTURE_RECORD = {
    'user': 'fixture-user', 'nonce': '8SWLGPbZ5DaKPcjr',
    'password': 'p5xxM6PWQybpBrKSmpr_oI_vi7dxPk4OR-u8h2EyNZE',
    'cipher': 'bound-v2', 'expires_at': '2999-01-01T00:00:00Z',
    'created_at': '2026-01-01T00:00:00Z',
}


class QuectelAuthTests(Base):
    def setUp(self):
        super().setUp()
        self.store = self.root / 'tokens.json'
        self.write_store()
        self.env = patch.dict(os.environ, {
            'JIRA_TOKEN': FIXTURE_TOKEN, 'JIRA_URL': 'https://ticket.quectel.com',
            'JIRA_TOKEN_STORE': str(self.store),
        })
        self.env.start()
        self.addCleanup(self.env.stop)

    def write_store(self, record=None):
        self.store.write_text(json.dumps({
            'version': 1,
            'tokens': {hashlib.sha256(FIXTURE_TOKEN.encode()).hexdigest():
                       copy.deepcopy(record or FIXTURE_RECORD)},
        }), encoding='utf-8')

    def test_plugin_environment_prefers_process_and_preserves_explicit_empty(self):
        with patch.dict(os.environ, {'JIRA_URL': 'https://process.invalid',
                                     'JIRA_TOKEN': '', 'JIRA_TOKEN_STORE': str(self.store)}):
            values = j._plugin_env()
        self.assertEqual(values['JIRA_URL'], 'https://process.invalid')
        self.assertEqual(values['JIRA_TOKEN'], '')

    def test_no_selected_token_does_not_scan_local_store(self):
        with patch.object(j, '_plugin_env', return_value={}), \
                patch('builtins.open', side_effect=AssertionError('must not scan')):
            self.assertIsNone(j._plugin_credentials('https://ticket.quectel.com'))

    def test_invalid_expiry_or_token_assignment_is_rejected(self):
        for expiry in ('not-a-date', '2999-01-01T00:00:00', 12, ''):
            self.write_store(dict(FIXTURE_RECORD, expires_at=expiry))
            with self.subTest(expiry=expiry), self.assertRaisesRegex(ValueError, '无法读取或校验'):
                j._plugin_credentials('https://ticket.quectel.com')
        with patch.object(j, '_plugin_env', return_value={'JIRA_TOKEN': 'JIRA_TOKEN=' + FIXTURE_TOKEN}):
            with self.assertRaisesRegex(ValueError, '格式不正确'):
                j._plugin_credentials('https://ticket.quectel.com')

    def test_legacy_v1_records_remain_compatible(self):
        # Legacy fixture uses the same dummy username/password and GCM nonce,
        # but the older token-only key derivation used by the official plugin.
        record = dict(FIXTURE_RECORD, cipher='legacy-v1', password=LEGACY_PASSWORD)
        self.write_store(record)
        self.assertEqual(j._plugin_credentials('https://ticket.quectel.com')['pw'], 'fixture-password')

    def test_real_cli_reuses_plugin_for_init_check_whoami_and_search(self):
        requests = []
        expected = 'Basic ' + base64.b64encode(b'fixture-user:fixture-password').decode()

        class Handler(BaseHTTPRequestHandler):
            def log_message(self, *args):
                pass

            def do_GET(self):
                requests.append((self.path, self.headers.get('Authorization')))
                if self.headers.get('Authorization') != expected:
                    status, data = 401, {'errorMessages': ['wrong fixture authorization']}
                elif self.path.startswith('/rest/api/2/myself'):
                    status, data = 200, {'name': 'fixture-user', 'displayName': 'Fixture User'}
                elif self.path.startswith('/rest/api/2/project'):
                    status, data = 200, [{'key': 'T', 'name': 'Fixture Project'}]
                else:
                    status, data = 200, {'total': 0, 'startAt': 0, 'maxResults': 10, 'issues': []}
                body = json.dumps(data).encode()
                self.send_response(status)
                self.send_header('Content-Type', 'application/json')
                self.send_header('Content-Length', str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        server = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            base = 'http://127.0.0.1:' + str(server.server_port)
            path = self.root / 'cli-config.yaml'
            env = os.environ.copy()
            for name in ('JIRA_PROFILE', 'JIRA_CREDS_PATH', 'JIRA_PROJECT_CONFIG_PATH'):
                env.pop(name, None)
            env.update(JIRA_URL=base, JIRA_NO_FOLDER_CFG='1',
                       JIRA_PROJECT_CONFIGS_DIR=str(self.root / 'project-configs'),
                       PYTHONIOENCODING='utf-8')
            for args in (['init', '--base-url', base, '--projects', 'T', '--use', 'T'],
                         ['init', '--check'], ['whoami'], ['search', '--max', '1']):
                result = subprocess.run([sys.executable, j.__file__, '--config', str(path), *args],
                                        env=env, cwd=str(self.root), stdin=subprocess.DEVNULL,
                                        capture_output=True, text=True, encoding='utf-8', timeout=20,
                                        creationflags=subprocess.CREATE_NO_WINDOW if os.name == 'nt' else 0)
                self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
                self.assertNotIn(FIXTURE_TOKEN, result.stdout + result.stderr)
                self.assertNotIn('fixture-password', result.stdout + result.stderr)
            saved = j._read_flat(str(path))
            self.assertEqual(saved['auth_source'], 'quectel-cli')
            self.assertEqual(saved['active_project'], 'T')
            self.assertFalse({'username', 'password', 'token'} & set(saved))
            self.assertTrue(requests)
            self.assertTrue(all(auth == expected for _, auth in requests))
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=5)

    def test_loading_explicit_account_or_bearer_never_uses_plugin(self):
        for text in ('username: selected\npassword: selected-password\n', 'token: selected-pat\n'):
            path = self.root / 'explicit.yaml'
            path.write_text(text, encoding='utf-8')
            with patch.object(j, '_plugin_credentials', side_effect=AssertionError('must not fall back')):
                result = j.load_creds(str(path))
            self.assertEqual(result['auth_source'], 'config')

    def test_plugin_never_expiring_authorization_is_supported(self):
        self.write_store(dict(FIXTURE_RECORD, expires_at='never'))
        self.assertEqual(j._plugin_credentials('https://ticket.quectel.com')['pw'], 'fixture-password')

    def test_expired_token_is_rejected_before_decryption(self):
        record = dict(FIXTURE_RECORD, expires_at='2000-01-01T00:00:00Z')
        self.write_store(record)
        with patch.object(j, '_decrypt_plugin_password') as decrypt:
            with self.assertRaisesRegex(ValueError, '已过期'):
                j._plugin_credentials('https://ticket.quectel.com')
            decrypt.assert_not_called()

    def test_other_instance_never_receives_plugin_credentials(self):
        with patch.object(j, '_decrypt_plugin_password') as decrypt:
            with self.assertRaisesRegex(ValueError, '另一个地址'):
                j._plugin_credentials('https://other.invalid')
            decrypt.assert_not_called()

    def test_tampered_user_or_ciphertext_is_rejected(self):
        for record in (dict(FIXTURE_RECORD, user='different-user'),
                       dict(FIXTURE_RECORD, password='B' + FIXTURE_RECORD['password'][1:])):
            self.write_store(record)
            with self.subTest(field=record['user']), self.assertRaisesRegex(ValueError, '校验失败'):
                j._plugin_credentials('https://ticket.quectel.com')

    def test_unknown_cipher_corrupt_store_or_missing_selected_token_is_rejected(self):
        with self.subTest(case='unknown cipher'):
            self.write_store(dict(FIXTURE_RECORD, cipher='future-v3'))
            with self.assertRaisesRegex(ValueError, '暂不支持'):
                j._plugin_credentials('https://ticket.quectel.com')
        for text in ('invalid-json', '{"version":1,"tokens":{}}'):
            self.store.write_text(text, encoding='utf-8')
            with self.subTest(case=text), self.assertRaisesRegex(ValueError, '无法读取或校验'):
                j._plugin_credentials('https://ticket.quectel.com')

    def test_no_plugin_gracefully_uses_original_initialization(self):
        path = self.root / 'new-manual.yaml'
        args = argparse.Namespace(config=str(path), profile=None, check=False,
                                  base_url=None, username=None, password=None, token=None,
                                  timeout=None, insecure=False, projects=None, use=None)
        with patch.object(j, '_plugin_env', return_value={}), \
                patch.object(j.sys.stdin, 'isatty', return_value=True), \
                patch.object(j, '_prompt', return_value='manual-user'), \
                patch.object(j.getpass, 'getpass', return_value='manual-password'), \
                patch.object(j, '_request', return_value=(200, {'name': 'manual-user'})), \
                patch.object(j, '_init_projects'), contextlib.redirect_stdout(io.StringIO()):
            j.cmd_init(args)
        self.assertEqual(j.C['user'], 'manual-user')
        self.assertEqual(j.C['auth_source'], 'config')
        self.assertNotIn('auth_source', j._read_flat(str(path)))

    def test_no_password_prompt_or_config_write_for_expired_plugin(self):
        self.write_store(dict(FIXTURE_RECORD, expires_at='2000-01-01T00:00:00Z'))
        path = self.root / 'expired.yaml'
        args = argparse.Namespace(config=str(path), profile=None, check=False,
                                  base_url=None, username=None, password=None, token=None,
                                  timeout=None, insecure=False, projects=None, use=None)
        with patch.object(j, '_prompt', side_effect=AssertionError('must not ask')), \
                patch.object(j.getpass, 'getpass', side_effect=AssertionError('must not ask')), \
                contextlib.redirect_stdout(io.StringIO()), contextlib.redirect_stderr(io.StringIO()), \
                self.assertRaises(SystemExit):
            j.cmd_init(args)
        self.assertFalse(path.exists())

    def test_renewed_selected_token_is_read_fresh(self):
        path = self.root / 'renewal.yaml'
        path.write_text('auth_source: quectel-cli\n', encoding='utf-8')
        self.assertEqual(j.load_creds(str(path))['user'], 'fixture-user')
        self.write_store(dict(FIXTURE_RECORD, expires_at='2000-01-01T00:00:00Z'))
        with contextlib.redirect_stderr(io.StringIO()), self.assertRaises(SystemExit):
            j.load_creds(str(path))

    def test_check_uses_plugin_without_reinitializing_or_rewriting(self):
        path = self.root / 'ready.yaml'
        path.write_text('base_url: https://ticket.quectel.com\nauth_source: quectel-cli\n'
                        'projects: T\nactive_project: T\n', encoding='utf-8')
        before = path.read_bytes()
        output = io.StringIO()
        with patch.object(j, '_request', return_value=(200, {'displayName': 'Fixture'})), \
                patch.object(j, '_project_cfg_dir', return_value=str(self.root / 'projects')), \
                contextlib.redirect_stdout(output):
            j._init_check(str(path))
        self.assertIn('已初始化', output.getvalue())
        self.assertIn('JIRA 插件', output.getvalue())
        self.assertEqual(path.read_bytes(), before)

    def test_init_reuses_plugin_without_prompts_or_copying_secrets(self):
        path = self.root / 'skill-config.yaml'
        args = argparse.Namespace(config=str(path), profile=None, check=False,
                                  base_url=None, username=None, password=None, token=None,
                                  timeout=None, insecure=False, projects=None, use=None)
        out = io.StringIO()
        with patch.object(j.sys.stdin, 'isatty', return_value=False), \
                patch.object(j, '_prompt', side_effect=AssertionError('unexpected username prompt')), \
                patch.object(j.getpass, 'getpass', side_effect=AssertionError('unexpected password prompt')), \
                patch.object(j, '_request', return_value=(200, {'name': 'fixture-user'})), \
                patch.object(j, '_init_projects'), contextlib.redirect_stdout(out):
            j.cmd_init(args)
        config = j._read_flat(str(path))
        self.assertEqual(config['base_url'], 'https://ticket.quectel.com')
        self.assertEqual(config['auth_source'], 'quectel-cli')
        self.assertFalse({'username', 'password', 'token'} & set(config))
        self.assertEqual(j.C['user'], 'fixture-user')
        self.assertEqual(j.C['pw'], 'fixture-password')
        self.assertFalse(j.C['token'])  # Plugin token is a local key, not JIRA Bearer.
        for secret in (FIXTURE_TOKEN, 'fixture-password'):
            self.assertNotIn(secret, path.read_text(encoding='utf-8') + out.getvalue())
